import{_ as r,C as i,o,c as s,j as e,a as h,E as l,a5 as n}from"./chunks/framework.D_J2JZBr.js";const _=JSON.parse('{"title":"CS290U 深度学习工程实践","description":"以真实数据、可重复评估和项目报告为核心，理解深度学习模型从复现到应用的工程链。","frontmatter":{"title":"CS290U 深度学习工程实践","description":"以真实数据、可重复评估和项目报告为核心，理解深度学习模型从复现到应用的工程链。"},"headers":[],"relativePath":"shanghaitech/courses/cs290u.md","filePath":"shanghaitech/courses/cs290u.md","lastUpdated":1795531638000}'),c={name:"shanghaitech/courses/cs290u.md"};function d(u,t,g,p,b,f){const a=i("CourseTable");return o(),s("div",null,[t[0]||(t[0]=e("h1",{id:"cs290u-深度学习工程实践",tabindex:"-1"},[h("CS290U 深度学习工程实践 "),e("a",{class:"header-anchor",href:"#cs290u-深度学习工程实践","aria-label":'Permalink to "CS290U 深度学习工程实践"'},"​")],-1)),l(a,{codes:"CS290U"}),t[1]||(t[1]=n('<p>课程表采用 <strong>2026–2027 学年</strong>信息；下文经验为 <strong>2026 秋版本</strong>。往届版本教师可能不同，且该学期笔记中的初始大纲与后续项目通知存在配分差异，应以最新正式通知为准。</p><h2 id="课程定位" tabindex="-1">课程定位 <a class="header-anchor" href="#课程定位" aria-label="Permalink to &quot;课程定位&quot;">​</a></h2><p>这门课不以“记住更多网络结构”为终点，而是让你完成数据准备、模型运行、训练或适配、评估、误差分析和成果展示。它适合将深度学习理论转化成可解释、可重复的工程实践。</p><p>官方开课表先修为 CS280；虽然往届笔记的基本信息写“先修无”，这里不把它解释成当前无先修。学习上还需要 Python、PyTorch、线性代数与基本优化知识。与<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee219">EE219</a>搭配时，可将本课的模型与数据理解带到算子、量化和硬件映射中；但两门课的作业与成果不得未经许可互相替代提交。</p><h2 id="内容主线" tabindex="-1">内容主线 <a class="header-anchor" href="#内容主线" aria-label="Permalink to &quot;内容主线&quot;">​</a></h2><p>2026 秋初始安排可归并为以下阶段；周次是往届版本，不是下一学期承诺。</p><table tabindex="0"><thead><tr><th>阶段</th><th>初始周次</th><th>主线与检查点</th></tr></thead><tbody><tr><td>理论与工程准备</td><td>1–2</td><td>MLP、反向传播、CNN / RNN / Transformer，以及训练与工程基础</td></tr><tr><td>二维视觉</td><td>4–5</td><td>在新数据上测试分割、检测等方法，分析预处理与数据分布差异</td></tr><tr><td>相机定位与三维</td><td>5–6</td><td>理解几何、对应关系和位姿；核对坐标、尺度与评估口径</td></tr><tr><td>点云处理</td><td>7–8</td><td>特征提取、配准与新环境中的误差分析</td></tr><tr><td>自定义项目</td><td>9–12</td><td>文献调研、方案、实现、评估、报告与展示</td></tr></tbody></table><p>后续笔记中的项目题目更具体，包括分类 / 检测 / SAM，以及 VGGT、VGGT-Omega、AnySplat 等前馈三维重建方法。因此学习路线应围绕能力组织，而非假设每届都按完全相同的模型清单开展。</p><h2 id="实验-项目" tabindex="-1">实验 / 项目 <a class="header-anchor" href="#实验-项目" aria-label="Permalink to &quot;实验 / 项目&quot;">​</a></h2><p>课程强调把已有模型放到新的测试环境中，观察领域偏移（Domain Shift）。报告不能停在“下载代码并跑通”：需要说明数据从哪里来、如何预处理、指标如何计算、哪些情况失败，以及可能原因是否得到实验支持。</p><p>建议采用四步证据链：</p><ol><li><strong>建立基线</strong>：固定源码版本、权重、依赖、数据与评价设置。</li><li><strong>迁移测试</strong>：区分预训练模型直接推理、重新训练和微调，不能混称“复现”。</li><li><strong>分析误差</strong>：检查图像分辨率、光照、坐标系、尺度、标注协议等可验证因素。</li><li><strong>开展对照</strong>：一次只改变明确因素，同时记录质量、速度、显存等指标的适用条件。</li></ol><p>自定义项目可涉及三维重建与新视角合成、生成模型，或已有任务的延伸。优先选能在期限内完成可靠评估的题目，而非只按模型规模决定难度。网页 Demo 展示可用性，但不替代定量结果，也不要公开含私人信息的采集数据。</p><h2 id="教材与资源" tabindex="-1">教材与资源 <a class="header-anchor" href="#教材与资源" aria-label="Permalink to &quot;教材与资源&quot;">​</a></h2><ul><li>当学期讲义、项目说明与授权代码为主要材料；现有资料不足以确认统一指定教材，不在这里虚构书目。</li><li><a href="https://pytorch.org/" target="_blank" rel="noreferrer">PyTorch</a>：查询数据加载、自动求导、训练和推理 API。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/research/tools">研究工具</a>：实验记录与代码管理。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/research/paper-reading">论文阅读</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/research/writing">科研写作</a>：解释基线、对照、失败案例与证据边界。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/computer-architecture/heterogeneous-systems">AI 硬件路线</a>：将模型算子和部署代价联系起来。</li></ul><h2 id="往届经验与建议" tabindex="-1">往届经验与建议 <a class="header-anchor" href="#往届经验与建议" aria-label="Permalink to &quot;往届经验与建议&quot;">​</a></h2><p><strong>2026 秋版本。</strong> 初始大纲笔记为互动与进度 10%、三个实验各 20%、自定义项目 30%；但后续 Project 2 通知笔记记为 30%，与初始表不一致。<strong>不能将两个版本直接拼接成总评表</strong>，本页也不替课程解决这一冲突。已知特点是项目、实验报告与展示占主要位置，而非以笔试为中心。</p><ul><li><strong>难点</strong>：环境依赖与显存需求、数据协议、相机和坐标约定，以及把结果变化归因到具体因素。</li><li><strong>准备</strong>：先熟悉 PyTorch 数据管线、模型加载、训练 / 推理模式、随机种子和基本日志。不要等到报告前才检查是否存下了评估结果。</li><li><strong>工具链</strong>：隔离环境、固定依赖和权重来源；保留完整命令及配置。下载成功或保存了一张图片，不等于完成了方法复现。</li><li><strong>项目组织</strong>：分工时明确数据、实现、评估与报告接口；对照必须使用同一口径。未知项和失败结果如实保留。</li><li><strong>报告</strong>：区分观察、解释与尚待验证的假设；不把一组成功截图写成普遍性能结论。</li></ul><h2 id="相关方向" tabindex="-1">相关方向 <a class="header-anchor" href="#相关方向" aria-label="Permalink to &quot;相关方向&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/ai-hardware">AI 硬件</a>：模型计算与硬件部署之间的接口。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/architecture">计算机体系结构</a>：性能测量与系统瓶颈。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/eda">EDA</a>：面向自动化与优化的交叉学习背景，而非本课已确认的专门教学主题。</li></ul><div class="info custom-block"><p class="custom-block-title">征集</p><p>如果你修过这门课，欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>补充最新正式考核说明、项目版本与中性经验。分享数据和 Demo 前请核对隐私与授权。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">SIST 2026–2027 学年开课表</a>：授课教师、学分与 CS280 先修。</li><li>维护者 2026 秋笔记《深度学习工程实践 CS290U》：初始课程安排、项目主题与后续通知记录；配分冲突未独立消解，因此不作为完整现行总评规则。</li></ul>',23))])}const k=r(c,[["render",d]]);export{_ as __pageData,k as default};
